head.script:
scwin.screenId = "uldmgt50013";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

scwin.obj = undefined; try { scwin.obj = /* sdd-asis-lifecycle:begin obj — as-is 원문 본문(전환 이관 · 포팅 적용됨) */opener.Potential.Provider/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50013' }); }

scwin.frameId = undefined; try { scwin.frameId = /* sdd-asis-lifecycle:begin frameId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.obj.ActiveFrame.FrameID/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50013' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50013.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_61_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_61_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_61_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.disuse()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50013.img_61_onclick' }); }
};

/**
 * @event
 * @name scwin.img_62_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_62_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_62_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50013.img_62_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Disuse
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Disuse = async function () {
    const sbmOptions = {
        id: "tx_fn_Disuse",
        method: "post",
        action: "/filing/updateForm.do",
        ref: "dma_DisuseReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50013.tx_fn_Disuse" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.disuse
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.disuse = async function () {
    /* sdd-asis-lifecycle:begin fn_Disuse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (($c.util.getComponent('cal_endDd').getValue() == null ? '' : String($c.util.getComponent('cal_endDd').getValue())) === '') {
        await $c.win.alert("폐지일자를 넣어 주세요.");
        return;
    }
    $c.util.getComponent('dma_DisuseReq').set('method', "updateDisuseForm");
    scwin.form_editForm.action = "/filing/updateForm.do";
    await scwin.tx_fn_Disuse();
    /* sdd-asis-lifecycle:end */
};
